('q_aj-prepositions_0','The cat is ... the box. (uvnitř)',ARRAY['in','on','at','under']::TEXT[],0,'In znamená v nebo uvnitř.',1,ARRAY[]::TEXT[],NULL,0,'c_aj-prepositions',NULL,NOW()),
('q_aj-prepositions_1','The book is ... the table. (na)',ARRAY['behind','under','on','in']::TEXT[],2,'On znamená na.',1,ARRAY[]::TEXT[],NULL,1,'c_aj-prepositions',NULL,NOW()),
('q_aj-prepositions_2','The ball is ... the chair. (pod)',ARRAY['under','on','in','next to']::TEXT[],0,'Under znamená pod.',1,ARRAY[]::TEXT[],NULL,2,'c_aj-prepositions',NULL,NOW()),
('q_aj-prepositions_3','Co znamená behind?',ARRAY['za','před','vedle','pod']::TEXT[],0,'Behind znamená za.',2,ARRAY[]::TEXT[],NULL,3,'c_aj-prepositions',NULL,NOW()),
('q_aj-prepositions_4','Co znamená next to?',ARRAY['vedle','mezi','nad','za']::TEXT[],0,'Next to znamená vedle.',2,ARRAY[]::TEXT[],NULL,4,'c_aj-prepositions',NULL,NOW()),
('q_aj-prepositions_5','Co znamená in front of?',ARRAY['uvnitř','pod','před','za']::TEXT[],2,'In front of znamená před.',2,ARRAY[]::TEXT[],NULL,5,'c_aj-prepositions',NULL,NOW()),
('q_aj-prepositions_6','Co znamená between?',ARRAY['za','mezi','před','pod']::TEXT[],1,'Between znamená mezi.',3,ARRAY[]::TEXT[],NULL,6,'c_aj-prepositions',NULL,NOW()),
('q_aj-prepositions_7','The lamp is ... the sofa and the window. (mezi)',ARRAY['between','under','on','behind']::TEXT[],0,'Lampa stojí mezi dvěma věcmi, proto between.',3,ARRAY[]::TEXT[],NULL,7,'c_aj-prepositions',NULL,NOW()),
('q_aj-prepositions_8','The dog is ... the house. (za domem)',ARRAY['behind','between','in','on']::TEXT[],0,'Za domem je behind the house.',3,ARRAY[]::TEXT[],NULL,8,'c_aj-prepositions',NULL,NOW()),
('q_aj-prepositions_9','Vyber správnou větu o tašce.',ARRAY['The bag under is the desk.','The bag is under the desk.','The bag is on the desk under.','The bag is in under the desk.']::TEXT[],1,'Pořadí je podmět, sloveso, předložka, podstatné jméno.',4,ARRAY[]::TEXT[],NULL,9,'c_aj-prepositions',NULL,NOW()),
('q_aj-prepositions_10','Doplň: The cat is ... the sofa. (na pohovce)',ARRAY['under','by','on','at']::TEXT[],2,'Na povrchu je on.',4,ARRAY[]::TEXT[],NULL,10,'c_aj-prepositions',NULL,NOW()),
('q_aj-prepositions_11','Jakou předložku použijeme v in the morning?',ARRAY['in','on','by','at']::TEXT[],0,'Ráno je in the morning.',4,ARRAY[]::TEXT[],NULL,11,'c_aj-prepositions',NULL,NOW()),
