('q_aj-prepositions_13','Která věta popisuje obrázek, kde kočka sedí na krabici?',ARRAY['The cat is behind the box.','The cat is under the box.','The cat is on the box.','The cat is in the box.']::TEXT[],2,'Kočka je na krabici, anglicky on the box.',5,ARRAY[]::TEXT[],NULL,13,'c_aj-prepositions',NULL,NOW()),
('q_aj-prepositions_14','Jaký je opak slovního spojení in front of?',ARRAY['next to','in','behind','between']::TEXT[],2,'Opakem před je za, anglicky behind.',5,ARRAY[]::TEXT[],NULL,14,'c_aj-prepositions',NULL,NOW())
