INSERT INTO "Question" ("id","prompt","options","correctIndex","explanation","difficulty","answers","hint","order","courseId","levelId","createdAt") VALUES
('q_cj-hlasky-pismena_0','Které písmeno je samohláska?',ARRAY['k','b','a','s']::TEXT[],2,'Samohlásky jsou a, e, i, o, u, y. Písmeno a je samohláska.',1,ARRAY[]::TEXT[],NULL,0,'c_cj-hlasky-pismena',NULL,NOW()),
('q_cj-hlasky-pismena_1','Kolik písmen má slovo MAMA?',ARRAY['2','4','5','3']::TEXT[],1,'M, A, M, A jsou čtyři písmena.',1,ARRAY[]::TEXT[],NULL,1,'c_cj-hlasky-pismena',NULL,NOW()),
('q_cj-hlasky-pismena_2','Které slovo začíná samohláskou?',ARRAY['dům','okno','stůl','kolo']::TEXT[],1,'Slovo okno začíná samohláskou o.',1,ARRAY[]::TEXT[],NULL,2,'c_cj-hlasky-pismena',NULL,NOW()),
('q_cj-hlasky-pismena_3','Které písmeno je souhláska?',ARRAY['e','a','o','m']::TEXT[],3,'Písmena a, e, o jsou samohlásky, m je souhláska.',2,ARRAY[]::TEXT[],NULL,3,'c_cj-hlasky-pismena',NULL,NOW()),
('q_cj-hlasky-pismena_4','Kolik samohlásek je ve slově KOLO?',ARRAY['4','1','3','2']::TEXT[],3,'Ve slově kolo jsou dvě samohlásky o.',2,ARRAY[]::TEXT[],NULL,4,'c_cj-hlasky-pismena',NULL,NOW()),
('q_cj-hlasky-pismena_5','Jaké je první písmeno abecedy?',ARRAY['B','A','O','Z']::TEXT[],1,'Abeceda začíná písmenem A.',2,ARRAY[]::TEXT[],NULL,5,'c_cj-hlasky-pismena',NULL,NOW()),
('q_cj-hlasky-pismena_6','Které písmeno je dlouhá samohláska?',ARRAY['a','b','á','c']::TEXT[],2,'Dlouhé samohlásky mají čárku nebo kroužek: á, é, í, ó, ú, ů, ý.',3,ARRAY[]::TEXT[],NULL,6,'c_cj-hlasky-pismena',NULL,NOW()),
('q_cj-hlasky-pismena_7','Které slovo má právě tři samohlásky?',ARRAY['banán','stůl','pomeranč','škola']::TEXT[],2,'Ve slově pomeranč jsou samohlásky o, e, a.',3,ARRAY[]::TEXT[],NULL,7,'c_cj-hlasky-pismena',NULL,NOW()),
('q_cj-hlasky-pismena_8','Kolik samohlásek je ve slově MAMINKA?',ARRAY['5','3','2','4']::TEXT[],1,'Samohlásky jsou a, i, a.',3,ARRAY[]::TEXT[],NULL,8,'c_cj-hlasky-pismena',NULL,NOW()),
('q_cj-hlasky-pismena_9','Kolik hlásek má slovo CHLEB?',ARRAY['3','6','4','5']::TEXT[],2,'Ch je jedna hláska, i když se píše dvěma písmeny: ch, l, e, b.',4,ARRAY[]::TEXT[],NULL,9,'c_cj-hlasky-pismena',NULL,NOW()),
('q_cj-hlasky-pismena_10','Které slovo má pět písmen, ale jen čtyři hlásky?',ARRAY['stolek','chyba','škola','mouka']::TEXT[],1,'Ch je jedna hláska, proto má chyba čtyři hlásky: ch, y, b, a.',4,ARRAY[]::TEXT[],NULL,10,'c_cj-hlasky-pismena',NULL,NOW()),
('q_cj-hlasky-pismena_11','Které písmeno následuje v české abecedě hned za písmenem C?',ARRAY['D','B','Č','Ch']::TEXT[],2,'Po C následuje Č a pak D.',4,ARRAY[]::TEXT[],NULL,11,'c_cj-hlasky-pismena',NULL,NOW()),
('q_cj-hlasky-pismena_12','Které slovo začíná souhláskou a končí samohláskou?',ARRAY['voda','oko','stůl','jas']::TEXT[],0,'Voda začíná na v a končí na a.',5,ARRAY[]::TEXT[],NULL,12,'c_cj-hlasky-pismena',NULL,NOW()),
('q_cj-hlasky-pismena_13','Kolik hlásek má slovo ŠKOLA?',ARRAY['6','5','3','4']::TEXT[],1,'Hlásky jsou š, k, o, l, a.',5,ARRAY[]::TEXT[],NULL,13,'c_cj-hlasky-pismena',NULL,NOW()),
('q_cj-hlasky-pismena_14','Které slovo má stejně písmen jako hlásek?',ARRAY['chrám','chyba','škola','chleba']::TEXT[],2,'Škola má pět písmen i pět hlásek, ostatní slova obsahují ch.',5,ARRAY[]::TEXT[],NULL,14,'c_cj-hlasky-pismena',NULL,NOW()),
('q_cj-slabiky-slova_0','Kolik slabik má slovo máma?',ARRAY['2','3','4','1']::TEXT[],0,'Slovo se dělí má-ma, jsou to dvě slabiky.',1,ARRAY[]::TEXT[],NULL,0,'c_cj-slabiky-slova',NULL,NOW()),
('q_cj-slabiky-slova_1','Kolik slabik má slovo auto?',ARRAY['3','1','4','2']::TEXT[],3,'Slovo se dělí au-to.',1,ARRAY[]::TEXT[],NULL,1,'c_cj-slabiky-slova',NULL,NOW()),
('q_cj-slabiky-slova_2','Co je slabika?',ARRAY['jedno písmeno','celá věta','část slova, kterou vyslovíme jedním výdechem','dvě slova']::TEXT[],2,'Slabiky jsou části slov, které vyslovíme jedním výdechem.',1,ARRAY[]::TEXT[],NULL,2,'c_cj-slabiky-slova',NULL,NOW()),
('q_cj-slabiky-slova_3','Kolik slabik má slovo banán?',ARRAY['4','3','1','2']::TEXT[],3,'Slovo se dělí ba-nán.',2,ARRAY[]::TEXT[],NULL,3,'c_cj-slabiky-slova',NULL,NOW()),
