('q_cj-souveti_5','Které souvětí je napsané správně?',ARRAY['Přišel jsem protože mě, pozvali.','Přišel jsem, protože mě pozvali.','Přišel, jsem protože mě pozvali.','Přišel jsem protože, mě pozvali.']::TEXT[],1,'Čárka patří před spojku protože.',2,ARRAY[]::TEXT[],NULL,5,'c_cj-souveti',NULL,NOW()),
('q_cj-souveti_6','Ve které větě chybí čárka?',ARRAY['Chtěl jsem jít ven ale pršelo.','Maminka vaří a táta čte.','Chtěl jsem jít ven, ale pršelo.','Mám psa i kočku.']::TEXT[],0,'Před ale píšeme čárku.',3,ARRAY[]::TEXT[],NULL,6,'c_cj-souveti',NULL,NOW()),
('q_cj-souveti_7','Která spojka je podřadicí?',ARRAY['protože','ale','nebo','a']::TEXT[],0,'Spojky a, ale a nebo jsou souřadicí.',3,ARRAY[]::TEXT[],NULL,7,'c_cj-souveti',NULL,NOW()),
('q_cj-souveti_8','Které souvětí je souřadné?',ARRAY['Zůstal jsem doma, protože pršelo.','Nevím, kdo to byl.','Řekl, že přijde.','Prší a fouká vítr.']::TEXT[],3,'Obě věty jsou na stejné úrovni, spojuje je a.',3,ARRAY[]::TEXT[],NULL,8,'c_cj-souveti',NULL,NOW()),
('q_cj-souveti_9','Které souvětí je podřadné?',ARRAY['Prší, ale svítí slunce.','Jdu ven a hraji si.','Čtu knihu nebo kreslím.','Zůstanu doma, protože jsem nemocný.']::TEXT[],3,'Věta protože jsem nemocný závisí na větě hlavní.',4,ARRAY[]::TEXT[],NULL,9,'c_cj-souveti',NULL,NOW()),
('q_cj-souveti_10','Co patří před spojku že ve větě Vím že přijdeš?',ARRAY['nic','tečka','čárka','dvojtečka']::TEXT[],2,'Správně: Vím, že přijdeš.',4,ARRAY[]::TEXT[],NULL,10,'c_cj-souveti',NULL,NOW()),
('q_cj-souveti_11','Jak se nazývá věta, která doplňuje větu hlavní (například že přijde)?',ARRAY['věta hlavní','věta vedlejší','věta tázací','věta přací']::TEXT[],1,'Vedlejší věta závisí na hlavní.',4,ARRAY[]::TEXT[],NULL,11,'c_cj-souveti',NULL,NOW()),
('q_cj-souveti_12','Kolik vět hlavních je v souvětí Prší, ale my půjdeme ven, protože máme pláštěnky?',ARRAY['1','3','4','2']::TEXT[],3,'Hlavní jsou Prší a my půjdeme ven, vedlejší je protože máme pláštěnky.',5,ARRAY[]::TEXT[],NULL,12,'c_cj-souveti',NULL,NOW()),
('q_cj-souveti_13','Která věta je vedlejší v souvětí Řekl mi, že přijde?',ARRAY['Řekl mi','mi, že','že přijde','řekl']::TEXT[],2,'Věta že přijde doplňuje větu Řekl mi.',5,ARRAY[]::TEXT[],NULL,13,'c_cj-souveti',NULL,NOW()),
('q_cj-souveti_14','Které souvětí je napsáno správně?',ARRAY['Nevím, jestli, přijde.','Nevím jestli přijde.','Nevím jestli, přijde.','Nevím, jestli přijde.']::TEXT[],3,'Čárka patří před spojku jestli.',5,ARRAY[]::TEXT[],NULL,14,'c_cj-souveti',NULL,NOW())
