('q_dej-pravek_0','Jak se nazývá nejstarší období lidských dějin před vznikem písma?',ARRAY['středověk','novověk','starověk','pravěk']::TEXT[],3,'Pravěk je doba před písmem.',1,ARRAY[]::TEXT[],NULL,0,'c_dej-pravek',NULL,NOW()),
('q_dej-pravek_1','Čím se živili lidé v pravěku?',ARRAY['lovem a sběrem','prací v továrně','psaním','obchodem']::TEXT[],0,'Lovci a sběrači.',1,ARRAY[]::TEXT[],NULL,1,'c_dej-pravek',NULL,NOW()),
('q_dej-pravek_2','Co pravěcí lidé objevili a využívali k zahřátí i vaření?',ARRAY['elektřinu','oheň','pára','plyn']::TEXT[],1,'Oheň byl velký objev.',1,ARRAY[]::TEXT[],NULL,2,'c_dej-pravek',NULL,NOW()),
