('q_mat-cisla-do-10_0','Které číslo je o 1 větší než 4?',ARRAY['5','3','6','7']::TEXT[],0,'Za čtyřkou následuje pětka.',1,ARRAY[]::TEXT[],NULL,0,'c_mat-cisla-do-10',NULL,NOW()),
('q_mat-cisla-do-10_1','Kolik je 3 + 2?',ARRAY['6','4','1','5']::TEXT[],3,'Tři a dva jsou dohromady pět.',1,ARRAY[]::TEXT[],NULL,1,'c_mat-cisla-do-10',NULL,NOW()),
('q_mat-cisla-do-10_2','Které z čísel je nejmenší: 7, 3, 9, 5?',ARRAY['7','5','9','3']::TEXT[],3,'Trojka je nejblíž nule, proto je nejmenší.',1,ARRAY[]::TEXT[],NULL,2,'c_mat-cisla-do-10',NULL,NOW()),
('q_mat-cisla-do-10_3','Kolik je 8 − 3?',ARRAY['5','6','11','4']::TEXT[],0,'Když z osmi odebereš tři, zbude pět.',2,ARRAY[]::TEXT[],NULL,3,'c_mat-cisla-do-10',NULL,NOW()),
('q_mat-cisla-do-10_4','Které číslo leží mezi 6 a 8?',ARRAY['5','10','7','9']::TEXT[],2,'Po šestce následuje sedmička a pak osmička.',2,ARRAY[]::TEXT[],NULL,4,'c_mat-cisla-do-10',NULL,NOW()),
('q_mat-cisla-do-10_5','Kolik prstů máš na dvou rukou?',ARRAY['8','12','10','5']::TEXT[],2,'Na každé ruce je pět prstů, 5 + 5 = 10.',2,ARRAY[]::TEXT[],NULL,5,'c_mat-cisla-do-10',NULL,NOW()),
('q_mat-cisla-do-10_6','Které znaménko patří místo otazníku: 6 ? 9',ARRAY['>','=','<','+']::TEXT[],2,'Šest je menší než devět, proto píšeme <.',3,ARRAY[]::TEXT[],NULL,6,'c_mat-cisla-do-10',NULL,NOW()),
('q_mat-cisla-do-10_7','Doplň: 4 + ? = 9',ARRAY['5','6','13','4']::TEXT[],0,'Ke čtyřem musíme přidat pět, abychom dostali devět.',3,ARRAY[]::TEXT[],NULL,7,'c_mat-cisla-do-10',NULL,NOW()),
('q_mat-cisla-do-10_8','Kolik je 10 − 7?',ARRAY['4','3','17','2']::TEXT[],1,'Z deseti odebereme sedm a zbudou tři.',3,ARRAY[]::TEXT[],NULL,8,'c_mat-cisla-do-10',NULL,NOW()),
