('q_mat-cisla-do-10_10','Která řada je seřazená od nejmenšího po největší?',ARRAY['2, 9, 5','5, 2, 9','2, 5, 9','9, 5, 2']::TEXT[],2,'Od nejmenšího: dva, pět, devět.',4,ARRAY[]::TEXT[],NULL,10,'c_mat-cisla-do-10',NULL,NOW()),
('q_mat-cisla-do-10_11','Kolik je 6 + 4 − 3?',ARRAY['7','13','5','9']::TEXT[],0,'6 + 4 = 10 a 10 − 3 = 7.',4,ARRAY[]::TEXT[],NULL,11,'c_mat-cisla-do-10',NULL,NOW()),
('q_mat-cisla-do-10_12','Maminka koupila 4 jablka a pak ještě 5. Kolik jich má?',ARRAY['9','10','1','8']::TEXT[],0,'4 + 5 = 9.',5,ARRAY[]::TEXT[],NULL,12,'c_mat-cisla-do-10',NULL,NOW()),
