('q_mat-cisla-do-10_14','V autobuse jelo 10 lidí a 6 jich vystoupilo. Kolik jich zůstalo?',ARRAY['4','16','3','6']::TEXT[],0,'10 − 6 = 4.',5,ARRAY[]::TEXT[],NULL,14,'c_mat-cisla-do-10',NULL,NOW()),
